185: function heldMovement(now) {
186:   if (titleActive || UI.active || Battle.busy || Game.state !== 'overworld') return;
187:   if (now - lastStep < 135) return;
188:   let dx = 0, dy = 0;
189:   if (Input.down('arrowup', 'w')) dy = -1;
190:   else if (Input.down('arrowdown', 's')) dy = 1;
191:   else if (Input.down('arrowleft', 'a')) dx = -1;
192:   else if (Input.down('arrowright', 'd')) dx = 1;
193:   if (dx || dy) { World.step(dx, dy); lastStep = now; }
194: }
