196: function loop(now) {
197:   const dt = Math.min(100, now - (loop._last || now)); loop._last = now;
198:   heldMovement(now);
199:   if (!titleActive) { World.update(dt); World.draw(); }
200:   requestAnimationFrame(loop);
201: }
