.menu-description { margin: 0 auto 16px; max-width: 650px; color: #dce3f7; font: 24px/1.1 'PixelBody', monospace; }
.menu-list { display: flex; flex-direction: column; gap: 8px; }
.menu-option {
  padding: 10px 14px; color: #f4f1e8; text-align: left; cursor: pointer;
